export function requireAuth(req: Request, _res: Response, next: NextFunction) {
  if (!req.user) return next(new HttpError(401, "Authentication required"));
  next();
}

export function requireRole(...roles: Array<"CUSTOMER" | "PROVIDER" | "ADMIN">) {
  return (req: Request, _res: Response, next: NextFunction) => {
    if (!req.user) return next(new HttpError(401, "Authentication required"));
    if (!roles.includes(req.user.role)) return next(new HttpError(403, "Insufficient permissions"));
    next();
  };
}

import type { NextFunction, Request, Response } from "express";
import { HttpError } from "./error";

export function requireSameOrigin(req: Request, _res: Response, next: NextFunction) {
  if (!["POST", "PUT", "PATCH", "DELETE"].includes(req.method)) return next();

  const origin = req.get("origin");
  if (origin && origin !== process.env.CLIENT_ORIGIN) {
    return next(new HttpError(403, "Cross-origin request rejected"));
  }
  next();
}

export function requireString(value: unknown, field: string, min = 1, max = 500): string {
  if (typeof value !== "string") throw new HttpError(400, `${field} must be a string`);
  const trimmed = value.trim();
  if (trimmed.length < min || trimmed.length > max) {
    throw new HttpError(400, `${field} must be between ${min} and ${max} characters`);
  }
  return trimmed;
}

export function requirePositiveInt(value: unknown, field: string, max = 10000000): number {
  const number = Number(value);
  if (!Number.isInteger(number) || number <= 0 || number > max) {
    throw new HttpError(400, `${field} must be a positive integer`);
  }
  return number;
}

import { Router } from "express";
import { prisma } from "../db";
import { hashPassword, verifyPassword } from "../lib/password";
import { createSession, destroySession, COOKIE_NAME } from "../lib/session";
import { requireAuth } from "../middleware/auth";
import { HttpError } from "../middleware/error";
