const router = Router();

router.post("/register", async (req, res) => {
  const name = requireString(req.body.name, "name", 2, 80);
  const email = requireString(req.body.email, "email", 5, 254).toLowerCase();
  const password = requireString(req.body.password, "password", 12, 200);
  const role = req.body.role === "PROVIDER" ? "PROVIDER" : "CUSTOMER";

  const existing = await prisma.user.findUnique({ where: { email } });
  if (existing) throw new HttpError(409, "An account with that email already exists");

  const user = await prisma.user.create({
    data: { name, email, passwordHash: await hashPassword(password), role }
  });

  await createSession(user.id, res);
  res.status(201).json({ user: { id: user.id, name: user.name, email: user.email, role: user.role } });
});

router.post("/login", async (req, res) => {
  const email = requireString(req.body.email, "email", 5, 254).toLowerCase();
  const password = requireString(req.body.password, "password", 1, 200);

  const user = await prisma.user.findUnique({ where: { email } });
  if (!user || !(await verifyPassword(password, user.passwordHash))) {
    throw new HttpError(401, "Invalid email or password");
  }

  await createSession(user.id, res);
  res.json({ user: { id: user.id, name: user.name, email: user.email, role: user.role } });
});

router.post("/logout", requireAuth, async (req, res) => {
  await destroySession(req.cookies?.[COOKIE_NAME], res);
  res.status(204).send();
});

router.get("/me", requireAuth, (req, res) => {
  res.json({ user: req.user });
});

