import { Router } from "express";
import { prisma } from "../db";
import { requireAuth, requireRole } from "../middleware/auth";
import { HttpError } from "../middleware/error";
import { requireString } from "../middleware/validate";

const router = Router();

router.post("/", requireAuth, requireRole("CUSTOMER"), async (req, res) => {
  const serviceId = requireString(req.body.serviceId, "serviceId", 10, 100);
  const scheduledAtText = requireString(req.body.scheduledAt, "scheduledAt", 10, 80);
  const scheduledAt = new Date(scheduledAtText);

  if (Number.isNaN(scheduledAt.getTime()) || scheduledAt <= new Date()) {
    throw new HttpError(400, "scheduledAt must be a valid future date");
  }

  const service = await prisma.service.findUnique({ where: { id: serviceId } });
  if (!service) throw new HttpError(404, "Service not found");

  const booking = await prisma.booking.create({
    data: { customerId: req.user!.id, serviceId, scheduledAt },
    include: { service: { include: { provider: { select: { id: true, name: true } } } } }
  });

  res.status(201).json({ booking });
});

router.get("/mine", requireAuth, async (req, res) => {
  const bookings = req.user!.role === "PROVIDER"
    ? await prisma.booking.findMany({
        where: { service: { providerId: req.user!.id } },
        include: { service: true, customer: { select: { id: true, name: true, email: true } }, review: true },
        orderBy: { scheduledAt: "asc" }
      })
    : await prisma.booking.findMany({
        where: { customerId: req.user!.id },
        include: { service: { include: { provider: { select: { id: true, name: true } } } }, review: true },
        orderBy: { scheduledAt: "asc" }
      });

  res.json({ bookings });
});

router.patch("/:id/status", requireAuth, async (req, res) => {
  const status = req.body.status;
  if (!["CONFIRMED", "COMPLETED", "CANCELLED"].includes(status)) {
    throw new HttpError(400, "Unsupported booking status");
  }

  const booking = await prisma.booking.findUnique({
    where: { id: req.params.id },
    include: { service: true }
  });
  if (!booking) throw new HttpError(404, "Booking not found");

  const isCustomer = booking.customerId === req.user!.id;
  const isProvider = booking.service.providerId === req.user!.id;
  const isAdmin = req.user!.role === "ADMIN";

  if (!isCustomer && !isProvider && !isAdmin) {
    throw new HttpError(403, "You cannot change this booking");
  }

  const allowedTransitions: Record<string, string[]> = {
    PENDING: ["CONFIRMED", "CANCELLED"],
    CONFIRMED: ["COMPLETED", "CANCELLED"],
    COMPLETED: [],
    CANCELLED: []
  };

  if (!allowedTransitions[booking.status]?.includes(status)) {
    throw new HttpError(409, `Cannot change a ${booking.status} booking to ${status}`);
  }

  if (status === "CONFIRMED" && !isProvider && !isAdmin) {
    throw new HttpError(403, "Only the provider can confirm a booking");
  }
  if (status === "COMPLETED" && !isProvider && !isAdmin) {
    throw new HttpError(403, "Only the provider can complete a booking");
  }
  if (status === "CANCELLED" && !isCustomer && !isProvider && !isAdmin) {
    throw new HttpError(403, "Only the customer, provider or admin can cancel a booking");
  }

  const updated = await prisma.booking.update({
    where: { id: booking.id },
    data: { status },
    include: { service: true }
  });

  res.json({ booking: updated });
});

