              <form className="search-grid" onSubmit={e => { e.preventDefault(); loadServices().catch(err => setError(err.message)); }}>
                <label>Search<input value={search} onChange={e => setSearch(e.target.value)} placeholder="plumbing, tutoring..." /></label>
                <label>City<input value={city} onChange={e => setCity(e.target.value)} placeholder="Bhubaneswar" /></label>
                <button className="primary" type="submit">Search</button>
              </form>
            </section>

            <section aria-labelledby="services-title">
              <div className="section-heading"><h2 id="services-title">Available services</h2><span>{services.length} result(s)</span></div>
              <div className="card-grid">
                {services.map(service => (
                  <article className="card" key={service.id}>
                    <div className="card-top"><span className="tag">{service.category}</span><strong>{money(service.priceCents)}</strong></div>
                    <h3>{service.title}</h3>
                    <p>{service.description}</p>
                    <p className="muted">{service.city} · Provider: {service.provider.name}</p>
                    <button className="primary" onClick={() => book(service)}>Request booking</button>
                  </article>
                ))}
              </div>
              {services.length === 0 && <div className="empty">No services match the current search. Providers can add the first listing after signing in.</div>}
            </section>
          </>
        )}

        {view === "bookings" && user && (
          <section>
            <div className="section-heading"><h1>{user.role === "PROVIDER" ? "Incoming bookings" : "My bookings"}</h1></div>
            <div className="booking-list">
              {bookings.map(booking => (
                <article className="panel" key={booking.id}>
                  <div className="section-heading">
                    <h2>{booking.service.title}</h2>
                    <span className={`status status-${booking.status.toLowerCase()}`}>{booking.status}</span>
                  </div>
                  <p>{new Date(booking.scheduledAt).toLocaleString()}</p>
                  <p className="muted">{user.role === "PROVIDER" ? `Customer: ${booking.customer?.name}` : `Provider: ${booking.service.provider.name}`}</p>
                  <div className="actions">
                    {user.role === "PROVIDER" && booking.status === "PENDING" && <button className="primary" onClick={() => changeStatus(booking, "CONFIRMED")}>Confirm</button>}
                    {user.role === "PROVIDER" && booking.status === "CONFIRMED" && <button className="primary" onClick={() => changeStatus(booking, "COMPLETED")}>Mark completed</button>}
                    {(booking.status === "PENDING" || booking.status === "CONFIRMED") && <button onClick={() => changeStatus(booking, "CANCELLED")}>Cancel</button>}
                    {user.role === "CUSTOMER" && booking.status === "COMPLETED" && !booking.review && <ReviewForm bookingId={booking.id} onDone={loadBookings} onError={setError} />}
                  </div>
                </article>
              ))}
              {bookings.length === 0 && <div className="empty">No bookings yet.</div>}
            </div>
          </section>
        )}

        {view === "account" && (
          <Account user={user} onUser={setUser} onError={setError} onLogout={logout} />
        )}
      </main>
    </div>
  );
}

function Account({ user, onUser, onError, onLogout }: { user: User | null; onUser: (u: User) => void; onError: (m: string) => void; onLogout: () => Promise<void> }) {
  if (user) {
    return (
      <section className="panel narrow">
        <p className="eyebrow">Account</p>
        <h1>{user.name}</h1>
        <p>{user.email}</p>
        <p className="muted">Role: {user.role}</p>
        <button onClick={() => onLogout().catch(e => onError(e.message))}>Sign out</button>
        {user.role === "PROVIDER" && <ProviderServiceForm onError={onError} />}
      </section>
    );
  }
  return <AuthForm onUser={onUser} onError={onError} />;
}

function AuthForm({ onUser, onError }: { onUser: (u: User) => void; onError: (m: string) => void }) {
  const [mode, setMode] = useState<"login" | "register">("login");
  const [role, setRole] = useState<"CUSTOMER" | "PROVIDER">("CUSTOMER");

  async function submit(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();
    const data = new FormData(e.currentTarget);
    try {
      const result = mode === "login"
        ? await api.login(String(data.get("email")), String(data.get("password")))
        : await api.register(String(data.get("name")), String(data.get("email")), String(data.get("password")), role);
      onUser(result.user);
    } catch (e) {
      onError(e instanceof Error ? e.message : "Authentication failed");
    }
  }

  return (
    <section className="panel narrow">
      <p className="eyebrow">Account</p>
      <h1>{mode === "login" ? "Sign in" : "Create an account"}</h1>
      <form onSubmit={submit} className="stack">
        {mode === "register" && <label>Name<input name="name" minLength={2} maxLength={80} required /></label>}
        <label>Email<input name="email" type="email" autoComplete="email" required /></label>
        <label>Password<input name="password" type="password" minLength={mode === "register" ? 12 : 1} autoComplete={mode === "login" ? "current-password" : "new-password"} required /></label>
        {mode === "register" && <label>Account type<select value={role} onChange={e => setRole(e.target.value as typeof role)}><option value="CUSTOMER">Customer</option><option value="PROVIDER">Provider</option></select></label>}
        <button className="primary" type="submit">{mode === "login" ? "Sign in" : "Register"}</button>
      </form>
      <button className="link-button" onClick={() => setMode(mode === "login" ? "register" : "login")}>{mode === "login" ? "Need an account?" : "Already have an account?"}</button>
    </section>
  );
}

function ProviderServiceForm({ onError }: { onError: (m: string) => void }) {
  async function submit(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();
    const data = new FormData(e.currentTarget);
    try {
      await api.createService({
        title: String(data.get("title")),
        description: String(data.get("description")),
        category: String(data.get("category")),
        city: String(data.get("city")),
        priceCents: Math.round(Number(data.get("price")) * 100)
      });
      e.currentTarget.reset();
      window.location.reload();
    } catch (e) {
      onError(e instanceof Error ? e.message : "Could not create service");
    }
  }

  return (
    <form className="stack divider" onSubmit={submit}>
      <h2>Create a service listing</h2>
      <label>Title<input name="title" minLength={5} maxLength={120} required /></label>
      <label>Description<textarea name="description" minLength={20} maxLength={2000} required /></label>
      <label>Category<input name="category" required /></label>
      <label>City<input name="city" required /></label>
      <label>Price (INR)<input name="price" type="number" min="1" step="0.01" required /></label>
      <button className="primary" type="submit">Publish service</button>
    </form>
  );
}

function ReviewForm({ bookingId, onDone, onError }: { bookingId: string; onDone: () => Promise<void>; onError: (m: string) => void }) {
  async function submit(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();
    const data = new FormData(e.currentTarget);
    try {
      await api.review(bookingId, Number(data.get("rating")), String(data.get("comment")));
      await onDone();
    } catch (e) {
      onError(e instanceof Error ? e.message : "Could not submit review");
    }
  }
  return (
    <form className="review-form" onSubmit={submit}>
      <label>Rating<select name="rating" defaultValue="5"><option value="5">5</option><option value="4">4</option><option value="3">3</option><option value="2">2</option><option value="1">1</option></select></label>
      <label>Comment<textarea name="comment" minLength={5} maxLength={1000} required /></label>
      <button className="primary" type="submit">Review</button>
    </form>
  );
}

